import{_ as o,o as c,c as a,a0 as t}from"./chunks/framework.BQGW-Zpy.js";const m=JSON.parse('{"title":"Module Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/modules.md","filePath":"reference/modules.md"}'),r={name:"reference/modules.md"};function i(d,e,s,n,l,h){return c(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="module-reference" tabindex="-1">Module Reference <a class="header-anchor" href="#module-reference" aria-label="Permalink to &quot;Module Reference&quot;">​</a></h1><h2 id="backend-services-hedera" tabindex="-1"><code>backend/services/hedera/</code> <a class="header-anchor" href="#backend-services-hedera" aria-label="Permalink to &quot;`backend/services/hedera/`&quot;">​</a></h2><h3 id="client-mjs" tabindex="-1"><code>client.mjs</code> <a class="header-anchor" href="#client-mjs" aria-label="Permalink to &quot;`client.mjs`&quot;">​</a></h3><ul><li><code>getClient()</code>, singleton, connected Hedera <code>Client</code>. Auto-detects ED25519 vs. ECDSA (secp256k1) key format from the DER prefix.</li><li><code>getOperatorAccountId()</code>, <code>getNetwork()</code>, <code>closeClient()</code></li></ul><h3 id="hashing-mjs" tabindex="-1"><code>hashing.mjs</code> <a class="header-anchor" href="#hashing-mjs" aria-label="Permalink to &quot;`hashing.mjs`&quot;">​</a></h3><ul><li><code>canonicalHash(record)</code>, deterministic SHA-256 over a recursively key-sorted JSON representation.</li><li><code>pseudoRef(identifier, pepper)</code>. HMAC-SHA256-based, truncated to 24 hex characters. Requires a pepper of at least 16 characters (<code>HEDERA_PSEUDO_PEPPER</code> in <code>.env</code>).</li></ul><h3 id="topic-mjs" tabindex="-1"><code>topic.mjs</code> <a class="header-anchor" href="#topic-mjs" aria-label="Permalink to &quot;`topic.mjs`&quot;">​</a></h3><ul><li><code>getOrCreateTopic({ memo })</code>, reuses <code>HEDERA_TOPIC_ID</code> from <code>.env</code> if set, otherwise creates a submit-key-protected HCS topic (private writes, public reads) and persists the new ID back to <code>.env</code>. Holds the compliance, quote, and routing anchors.</li><li><code>getOrCreateCompletionTopic(submitKeyList, { memo })</code>, reuses <code>HEDERA_COMPLETION_TOPIC_ID</code> if set, otherwise creates a dedicated second HCS topic whose submit key is the 2-of-2 partner <code>KeyList</code> rather than the operator key. This is what makes the completion schedule genuinely wait for both partner signatures instead of auto-executing at creation.</li><li><code>topicHashscanUrl(topicId)</code></li></ul><h3 id="thresholdaccount-mjs" tabindex="-1"><code>thresholdAccount.mjs</code> <a class="header-anchor" href="#thresholdaccount-mjs" aria-label="Permalink to &quot;`thresholdAccount.mjs`&quot;">​</a></h3><ul><li><code>getOrCreateThresholdAccount({ usdcTokenId })</code>, reuses <code>INTERMEDIARY_ACCOUNT_ID</code> / <code>INTERMEDIARY_SOURCE_KEY</code> / <code>INTERMEDIARY_DEST_KEY</code> from <code>.env</code> if set, otherwise creates the 2-of-2 threshold-key intermediary settlement account and associates it with the settlement stablecoin. Returns <code>{ accountId, sourcePartnerKey, destinationPartnerKey }</code>.</li></ul><h3 id="scheduleanchor-mjs" tabindex="-1"><code>scheduleAnchor.mjs</code> <a class="header-anchor" href="#scheduleanchor-mjs" aria-label="Permalink to &quot;`scheduleAnchor.mjs`&quot;">​</a></h3><ul><li><code>createCompletionSchedule(topicId, record)</code>, wraps a <code>TopicMessageSubmitTransaction</code> (the completion message) inside a <code>ScheduleCreateTransaction</code> on the dedicated completion topic. Sits pending until both partner keys sign. Expiry is 48 hours, well under HSS&#39;s 62-day ceiling (HIP-423).</li><li><code>signCompletionSchedule(scheduleId, signerPrivateKey)</code>, submits one required signature. Called once per partner key. Returns whether this signature completed the set and triggered execution.</li></ul><h3 id="anchor-mjs" tabindex="-1"><code>anchor.mjs</code> <a class="header-anchor" href="#anchor-mjs" aria-label="Permalink to &quot;`anchor.mjs`&quot;">​</a></h3><ul><li><code>anchorComplianceRecord(topicId, record)</code></li><li><code>anchorQuote(topicId, quote)</code></li><li><code>anchorRoutingDecision(topicId, record)</code></li></ul><p>All three share one internal mechanism: hash the record, submit a small pointer message (<code>{ kind, recordId, transferRef, recordHash, appTimestamp }</code>) to HCS, return the sequence number, transaction ID, and HashScan links.</p><h3 id="verify-mjs" tabindex="-1"><code>verify.mjs</code> <a class="header-anchor" href="#verify-mjs" aria-label="Permalink to &quot;`verify.mjs`&quot;">​</a></h3><ul><li><code>fetchMirrorMessage(topicId, sequenceNumber, { retries, delayMs })</code> , polls a public Mirror Node with backoff (consensus can lag a submission by a few seconds).</li><li><code>decodeMirrorMessage(mirrorResponse)</code></li><li><code>verifyRecord(record, anchoredMessage)</code>, recomputes the hash of <code>record</code> as it exists now and compares against what was anchored. Returns <code>{ verified: true }</code> or <code>{ verified: false, reason }</code>.</li></ul><h2 id="backend-services-settlement" tabindex="-1"><code>backend/services/settlement/</code> <a class="header-anchor" href="#backend-services-settlement" aria-label="Permalink to &quot;`backend/services/settlement/`&quot;">​</a></h2><h3 id="corridorconfig-mjs" tabindex="-1"><code>corridorConfig.mjs</code> <a class="header-anchor" href="#corridorconfig-mjs" aria-label="Permalink to &quot;`corridorConfig.mjs`&quot;">​</a></h3><ul><li><code>PARTNER_CHAIN_SUPPORT</code>, maintained config of which chains each sandbox partner accepts.</li><li><code>COMPLIANT_STABLECOIN_CHAINS</code>, chains with a natively-issued, MiCA-compliant EMT (USDC/EURC).</li><li><code>HEDERA_SAFE_AMOUNT_USD</code>, the tunable liquidity-safety threshold.</li><li><code>FALLBACK_CHAIN_PRIORITY</code>, <code>BRIDGE_METHOD_BY_CHAIN</code></li></ul><h3 id="liquidity-mjs" tabindex="-1"><code>liquidity.mjs</code> <a class="header-anchor" href="#liquidity-mjs" aria-label="Permalink to &quot;`liquidity.mjs`&quot;">​</a></h3><ul><li><code>fetchHederaStablecoinLiquidityUsd({ forceRefresh })</code>, a real call to SaucerSwap&#39;s own <code>/stats</code> REST endpoint, Hedera&#39;s largest DEX and a named ecosystem partner rather than a third-party aggregator, cached for 15 minutes.</li><li><code>RESEARCHED_FALLBACK_TVL_USD</code>, a conservative, cited fallback figure used only if the live call fails.</li></ul><h3 id="corridorrouter-mjs" tabindex="-1"><code>corridorRouter.mjs</code> <a class="header-anchor" href="#corridorrouter-mjs" aria-label="Permalink to &quot;`corridorRouter.mjs`&quot;">​</a></h3><ul><li><code>chooseSettlementRail(partnerId, amountUsd, { liquidityFetcher })</code> , the routing decision. <code>liquidityFetcher</code> is injectable, which is what makes the branching logic testable without a network call (see <code>__tests__/router.test.mjs</code>).</li></ul><h3 id="execute-mjs" tabindex="-1"><code>execute.mjs</code> <a class="header-anchor" href="#execute-mjs" aria-label="Permalink to &quot;`execute.mjs`&quot;">​</a></h3><ul><li><code>executeOnHedera({ amountUsd, destinationAccountId })</code>, a real HTS token transfer on testnet.</li><li><code>executeOnUnavailableChain(chain, { amountUsd })</code>, a clearly-labeled, structured non-execution for any chain without funded credentials.</li><li><code>executeSettlement(decision, opts)</code>, the single entry point that dispatches between the two.</li></ul>',26)])])}const p=o(r,[["render",i]]);export{m as __pageData,p as default};
